/** * WOL Win 10 Driver (Custom) * Device Driver for Hubitat Elevation * * Purpose: * Transmits Wake-on-LAN (WOL) UDP magic packets across local or remote IP targets * to power on networked workstations. * * Notes: * Custom Health Check Implementation * - Intentionally NOT using Hubitat's native 'Health Check' capability. * - Hubitat's native capability exposes an unwanted "Ping" UI control button *   and does not provide the phase-anchored scheduling, timeout guards, or trace  *   logging behavior required by this driver architecture. * - healthStatus attribute signifies valid configuration readiness ('online') rather than  *   verifying active workstation ACPI power state. **//** * Copyright 2026 James Shimota * * Licensed under the Apache License, Version 2.0 (the "License"); * you may not use this file except in compliance with the License. * You may obtain a copy of the License at: * *     http://www.apache.org/licenses/LICENSE-2.0 * * Unless required by applicable law or agreed to in writing, software * distributed under the License is distributed on an "AS IS" BASIS, * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. * See the License for the specific language governing permissions and * limitations under the License. **//** * Changelog: * v1.0.2   09/10/26    jshimota    Added off() command handler with info log output to satisfy Switch capability requirement. * v1.0.1   09/10/26    jshimota    Added MAC/Port normalization & validation, fixed conditional SecureOn packet assembly, removed dead timeout code. * v1.0.0   09/10/26    jshimota    Initial release based on standardized driver template v1.0.11. **/// [KEEP-EXACT] See possible changelog.txt for past changelog history.static String version() { return '1.0.2' }def timeStamp() { return "2026/09/10 02:51 PM" }import groovy.transform.Fieldmetadata {    definition (        name: "WOL Win 10 Driver (Custom)",         namespace: "jshimota",         author: "James Shimota",         importUrl: ""    ) {        capability "Actuator"        capability "Configuration"        capability "Refresh"        capability "Momentary"        capability "Switch"        capability "PushableButton"        // Attributes        attribute "healthStatus", "enum", ["unknown", "offline", "online"]        // Custom Commands        command "wake"        command "Health Check"        command "resetDriver"    }    preferences {        input name: "myMac", type: "text", title: "<b>MAC Address</b>", description: "MAC address of the targeted workstation", required: true        input name: "myIP", type: "text", title: "<b>IP Address</b>", description: "Default: 255.255.255.255 (Subnet Broadcast)", defaultValue: "255.255.255.255", required: false        input name: "myPort", type: "number", title: "<b>Port</b>", description: "Default: 7", defaultValue: 7, required: false        input name: "mySecureOn", type: "text", title: "<b>SecureOn Password</b>", description: "Optional 12-character hex password", required: false        input name: "HealthCheckInterval", type: "enum", title: "<b>Health Check Interval</b>", options: HealthCheckIntervalOpts.options, defaultValue: HealthCheckIntervalOpts.defaultValue, description: "<i>Changes how often the driver executes a Health Check to verify configuration validity.<br><b>Note:</b> This is a custom driver routine and is NOT the native Hubitat Elevation platform Health Check service.</i>"        // Independent Logging Switches        input name: "logInfoEnable", type: "bool", title: "Logging - Enable Info Logging", description: "Enable to output normal activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logErrorEnable", type: "bool", title: "Logging - Enable Error Logging", description: "Enable to output error activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logWarnEnable", type: "bool", title: "Logging - Enable Warning Logging", description: "Enable to output warning activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logDebugEnable", type: "bool", title: "Logging - Enable Debug Logging", description: "Enable to output debugging activity to log<br>Default: <b>Off</b><br>(Is turned on for 30 minutes after Initialized or first installed)", defaultValue: false, required: true        input name: "logTraceEnable", type: "bool", title: "Logging - Enable Trace Logging", description: "Enable to output tracing activity to log<br>Default: <b>Off</b>", defaultValue: false, required: true    }}// Single-Shot Version Demarcation Trace Logging Helper Routineprivate void checkAndLogVersionDemarcation() {    String currentVer = version()    if (state.driverVersion != currentVer) {        logTrace "=================== DRIVER VERSION UPDATE: v${currentVer} (${timeStamp()}) ==================="        state.driverVersion = currentVer    }}def refresh() {    logInfo "refresh() requested"    return executeHealthCheck()}/* =========================================================================================   COMMAND HANDLERS & HELPERS   ========================================================================================= */void on() { wake() }void off() {    logInfo "off() command received: 'Off' was triggered, but Wake-on-LAN is a wake-only action and has no turn-off functionality."}void push() { wake() }void push(buttonNumber) { wake() }private String normalizeMac(String mac) {    if (!mac) return null    String normalized = mac.replaceAll(/[^0-9A-Fa-f]/, '').toUpperCase()    return (normalized ==~ /[0-9A-F]{12}/) ? normalized : null}void wake() {    logInfo "wake() command executed"        String macHEX = normalizeMac(myMac)    if (!macHEX) {        logError "Invalid MAC Address '${myMac}'. WOL transmission aborted."        updateAttribute("healthStatus", "offline")        return    }    Integer port = myPort ? myPort.toInteger() : 7    if (port < 1 || port > 65535) {        logError "Invalid UDP port '${myPort}'. WOL transmission aborted."        updateAttribute("healthStatus", "offline")        return    }    String ip = myIP ?: "255.255.255.255"    String command = "FFFFFFFFFFFF" + (macHEX * 16)    if (mySecureOn) {        String cleanSecureOn = mySecureOn.replaceAll(/[^0-9A-Fa-f]/, '').toUpperCase()        if (cleanSecureOn ==~ /[0-9A-F]{12}/) {            command += cleanSecureOn        } else {            logWarn "SecureOn password '${mySecureOn}' is invalid (must be 12 hex characters). Transmitting packet without SecureOn payload."        }    }    def myHubAction = new hubitat.device.HubAction(        command,        hubitat.device.Protocol.LAN,        [            type: hubitat.device.HubAction.Type.LAN_TYPE_UDPCLIENT,            destinationAddress: "${ip}:${port}",            encoding: hubitat.device.HubAction.Encoding.HEX_STRING        ]    )    sendHubCommand(myHubAction)    logInfo "Sent WOL magic packet to MAC ${macHEX} (${ip}:${port})"    updateAttribute("healthStatus", "online")}/* =========================================================================================   HUBITAT LIFECYCLE ROUTINES   ========================================================================================= */void installed() {    checkAndLogVersionDemarcation()    logInfo "Installing driver v${version()} (${timeStamp()})..."        initializeHealthCheckPhase()    sendEvent(name: "healthStatus", value: "unknown")    sendEvent(name: "numberOfButtons", value: 1)    initialize(true)}void updated() {    checkAndLogVersionDemarcation()    logInfo "Preferences updated"    String cleanMac = normalizeMac(myMac)    device.updateDataValue("MAC", cleanMac ?: "")    device.updateDataValue("SecureOn", mySecureOn ? "configured" : "none")    device.updateDataValue("IP", myIP ?: "255.255.255.255")    device.updateDataValue("Port", myPort ? "${myPort}" : "7")    device.updateDataValue("parentDriver", "WOL Win 10 (Custom)")    device.updateDataValue("driverVersion", version())        sendEvent(name: "numberOfButtons", value: 1)    initialize(false)}def configure() {    checkAndLogVersionDemarcation()    logInfo "configure() requested; performing immediate configuration check."        sendEvent(name: "numberOfButtons", value: 1)    initialize(false)        return executeHealthCheck()}private void initialize(Boolean isInstall = false) {    checkAndLogVersionDemarcation()    unschedule("disableDebugLogging")    if (device.currentValue("healthStatus") == null) {        sendEvent(name: "healthStatus", value: "unknown")    }    // Centralized Health Check Scheduler    final int interval = settings.HealthCheckInterval != null ? settings.HealthCheckInterval.toInteger() : 480    if (interval > 0) {        scheduleHealthCheck("executeHealthCheckScheduled", interval)    } else {        unschedule("executeHealthCheckScheduled")    }    if (isInstall) {        device.updateSetting("logDebugEnable", [type: "bool", value: true])        logInfo "Debug logging enabled for 30 minutes."        runIn(1800, "disableDebugLogging")    } else if (getSettingBool("logDebugEnable", false)) {        logInfo "Debug logging enabled. Will automatically turn off in 30 minutes."        runIn(1800, "disableDebugLogging", [overwrite: false])    } else {        unschedule("disableDebugLogging")    }}/* =========================================================================================   HEALTH CHECK ROUTINE TEMPLATE (CUSTOM HEALTH CHECK ARCHITECTURE)   ========================================================================================= */List<String> "Health Check"() {    return executeHealthCheck()}void executeHealthCheckScheduled() {    List<String> cmds = executeHealthCheck()    if (cmds) sendHubCommand(new hubitat.device.HubMultiAction(cmds, hubitat.device.Protocol.LAN))}private List<String> executeHealthCheck() {    logDebug "Executing configuration Health Check..."    String cleanMac = normalizeMac(myMac)    Integer port = myPort ? myPort.toInteger() : 7    if (cleanMac && (port >= 1 && port <= 65535)) {        logInfo "Health Check: WOL configuration is valid."        updateAttribute("healthStatus", "online")    } else {        logWarn "Health Check failed: MAC Address or Port configuration is invalid."        updateAttribute("healthStatus", "offline")    }    return []}private void initializeHealthCheckPhase() {    if (state.healthCheckStartHour == null) state.healthCheckStartHour = new Random().nextInt(24)    if (state.healthCheckStartMinute == null) state.healthCheckStartMinute = new Random().nextInt(60)}private void scheduleHealthCheck(String methodToSchedule, int intervalMin) {    unschedule(methodToSchedule)    initializeHealthCheckPhase()    final int h = state.healthCheckStartHour as Integer    final int m = state.healthCheckStartMinute as Integer    logInfo "Scheduling Health Check every ${intervalMin} minutes anchored at ${String.format('%02d:%02d', h, m)} daily"    switch (intervalMin) {        case 60:            schedule("0 ${m} * ? * * *", methodToSchedule)            break        case 240:            String h4 = [0, 4, 8, 12, 16, 20].collect { (it + h) % 24 }.sort().join(",")            schedule("0 ${m} ${h4} ? * * *", methodToSchedule)            break        case 480:            String h8 = [0, 8, 16].collect { (it + h) % 24 }.sort().join(",")            schedule("0 ${m} ${h8} ? * * *", methodToSchedule)            break        case 720:            String h12 = [0, 12].collect { (it + h) % 24 }.sort().join(",")            schedule("0 ${m} ${h12} ? * * *", methodToSchedule)            break        case 1440:            schedule("0 ${m} ${h} ? * * *", methodToSchedule)            break        default:            logError "Unsupported Health Check interval '${intervalMin}' specified. Disabling schedule."            break    }}/* =========================================================================================   MASTER UTILITY ROUTINES & LOGGING ENGINE   ========================================================================================= */void disableDebugLogging() {    if (getSettingBool("logDebugEnable", false)) {        logWarn "30 minutes have elapsed. Automatically disabling debug logging."        device.updateSetting("logDebugEnable", [type: "bool", value: false])    }}void resetDriver() {    logInfo "Starting full driver reset..."        Object savedHour = state.healthCheckStartHour    Object savedMinute = state.healthCheckStartMinute    clearAllSchedules()    clearAllAttributes()    clearAllDriverStates()    if (savedHour != null) state.healthCheckStartHour = savedHour    if (savedMinute != null) state.healthCheckStartMinute = savedMinute    initialize(false)    logInfo "Driver reset process completed and re-initialized."}void clearAllDriverStates() {    logInfo "Clearing all driver states..."    state.clear()    logInfo "All states have been cleared."}void clearAllAttributes() {    logInfo "Clearing driver healthStatus attribute..."    device.deleteCurrentState("healthStatus")    logInfo "Attributes cleared."}void clearAllSchedules() {    logInfo "Clearing all scheduled jobs (including orphaned schedules)..."    unschedule()    logInfo "All scheduled jobs have been successfully cleared."}private void updateAttribute(final String attribute, final Object value, final String unit = null, final String type = null) {    final String currentVal = device.currentValue(attribute)?.toString()    if (currentVal == value?.toString()) return    final String descriptionText = "${device.displayName} - ${attribute} was set to ${value}${unit ?: ''}"    logInfo descriptionText    sendEvent(name: attribute, value: value, unit: unit, type: type, descriptionText: descriptionText)}private void logMessage(String level, String msg) {    String lowerLevel = level?.toLowerCase() ?: "info"    String devName = device.displayName ?: "Device Driver"        String settingKey = "log${lowerLevel.capitalize()}Enable"    Boolean defaultEnabled = (lowerLevel in ["info", "warn", "error"])    if (getSettingBool(settingKey, defaultEnabled)) {        log."${lowerLevel}" "${devName}: ${msg}"    }}private void logInfo(String msg)  { logMessage("info", msg) }private void logDebug(String msg) { logMessage("debug", msg) }private void logTrace(String msg) { logMessage("trace", msg) }private void logWarn(String msg)  { logMessage("warn", msg) }private void logError(String msg) { logMessage("error", msg) }private Boolean getSettingBool(String key, Boolean defaultVal = false) {    return settings[key] != null ? settings[key] as Boolean : defaultVal}// Constants@Field static final Map HealthCheckIntervalOpts = [    defaultValue: 480,    options: [ 60: "Every Hour", 240: "Every 4 Hours", 480: "Every 8 Hours", 720: "Every 12 Hours", 1440: "Every 24 Hours", 0: "Disabled" ]]